<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { creditChild, reverseChildEntry, refundSupplyPoints, saveOffer, supplyBalance, supplyCatalog } from '@/api/supply'
import type { SupplyBalance, SupplyComponent, SupplyRow, SupplyEntry, SupplyUsage } from '@/api/supply'
import { useAuthStore } from '@/stores/auth'
import CustomSupplyReviewPanel from '@/components/models/CustomSupplyReviewPanel.vue'
const auth = useAuthStore(), rows = ref<SupplyRow[]>([]), balance = ref<SupplyBalance | null>(null), selected = ref<SupplyRow | null>(null)
const error = ref(''), busy = ref(false), message = ref(''), saleMarkup = ref<SupplyComponent[]>([]), supplyMarkup = ref<SupplyComponent[]>([])
const readOnly = computed(() => !auth.can('pricing_rules.manage') || (auth.user?.organizationContext?.authorizationSource === 'license-center' && (auth.user.organizationContext.centralLicenseActive !== true || auth.user.organizationContext.organizationStatus !== 'enabled')))
const reversalEntry = ref<SupplyEntry | null>(null), reversalReason = ref(''), reversalRequestId = ref('')
const canReverse = computed(() => first.value && auth.user?.organizationContext?.isOwner === true && auth.can('credits.manage'))
const canRefundPoints = computed(() => auth.user?.organizationContext?.isOwner === true && auth.can('credits.manage'))
const refundUsage = ref<SupplyUsage | null>(null), refundReason = ref(''), refundCommand = ref('')
const first = computed(() => auth.user?.organizationContext?.organizationLevel === 1)
const canReviewCustom = computed(() => !readOnly.value && first.value && auth.user?.organizationContext?.authorizationSource === 'license-center' && auth.user.organizationContext.isOwner === true && auth.user.organizationContext.modelMode === 'custom' && auth.can('model_providers.manage'))
const form = reactive({ enabled: true, pointsPerCny: '1', consumptionMultiplier: '1', effectiveAt: '' }), credit = reactive({ childId: '', amount: '', receipt: '', requestId: crypto.randomUUID() })
async function perform(operation: () => Promise<unknown>) { busy.value = true; error.value = ''; message.value = ''; try { await operation() } catch (e) { error.value = e instanceof Error ? e.message : '操作失败' } finally { busy.value = false } }
async function load() { [rows.value, balance.value] = await Promise.all([readOnly.value ? Promise.resolve([]) : supplyCatalog(), supplyBalance()]) }
function selectReversal(entry: SupplyEntry) { reversalEntry.value = entry; reversalReason.value = ''; reversalRequestId.value = crypto.randomUUID() }
async function reverse() {
  if (!reversalEntry.value) return
  await perform(async () => { await reverseChildEntry(reversalEntry.value!.organizationId, { entryId: reversalEntry.value!.id, requestId: reversalRequestId.value, reason: reversalReason.value }); reversalEntry.value = null; await load(); message.value = '已追加供货冲正流水；终端积分未变更。' })
}
function selectRefund(item: SupplyUsage) { refundUsage.value = item; refundReason.value = ''; refundCommand.value = crypto.randomUUID() }
async function refundPoints() {
  if (!refundUsage.value) return
  await perform(async () => { const result = await refundSupplyPoints(refundUsage.value!.requestId, { commandId: refundCommand.value, reason: refundReason.value }); refundUsage.value = null; await load(); message.value = `已退回 ${result.points} 积分；上游费用保留。` })
}
function edit(row: SupplyRow) {
  selected.value = row
  const empty = row.model.price.components.map(item => ({ ...item, amount: '0.000000' }))
  saleMarkup.value = JSON.parse(JSON.stringify(row.offer?.saleMarkup?.length ? row.offer.saleMarkup : empty))
  supplyMarkup.value = JSON.parse(JSON.stringify(row.offer?.supplyMarkup?.length ? row.offer.supplyMarkup : empty))
  form.enabled = row.offer?.enabled ?? true; form.pointsPerCny = row.offer?.pointsPerCny || '1'
  form.consumptionMultiplier = row.offer?.consumptionMultiplier ?? '1'; form.effectiveAt = ''
}
async function save() { if (!selected.value) return; await perform(async () => {
  const result = await saveOffer({ modelId: selected.value!.model.id, ...form, effectiveAt: form.effectiveAt ? new Date(form.effectiveAt).getTime() : undefined,
    saleMarkup: saleMarkup.value, supplyMarkup: supplyMarkup.value, expectedVersion: selected.value!.offer?.version || 0 })
  selected.value = null; await load(); message.value = result.priceEffectiveAt && result.priceEffectiveAt > Date.now() ? `调价已发布，将于 ${new Date(result.priceEffectiveAt).toLocaleString()} 生效，之前继续使用原价。` : '供货配置已保存'
}) }

async function topup() { await perform(async () => { await creditChild(credit.childId, credit); credit.requestId = crypto.randomUUID(); credit.amount = ''; credit.receipt = ''; await load(); message.value = '充值已审核入账' }) }
onMounted(() => perform(load))
</script>
<template>
  <section class="management-page supply-page"><header class="page-heading"><div><h1>模型供货与收益</h1><p>按上游供货价加价，分别记录用户积分与代理预付额度。</p></div><button class="secondary-button" :disabled="busy" @click="perform(load)">刷新</button></header>
    <p v-if="error" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p>
    <CustomSupplyReviewPanel v-if="canReviewCustom" @saved="perform(load)" />
    <article v-if="balance" class="panel-card"><h2>{{ first ? '供货经营' : '上游预付余额' }}</h2><p v-if="!first">余额 ¥{{ balance.wallet.balance }} · 预占 ¥{{ balance.wallet.reserved }}</p><p>待结算请求 {{ balance.unsettled }} 笔</p><div v-if="balance.totals"><p>累计原价 ¥{{ balance.totals.listSalesAmount }} · 折后计价 ¥{{ balance.totals.salesAmount }} · 营销补贴 ¥{{ balance.totals.marketingSubsidy }}</p><p>累计供货支出 ¥{{ first ? balance.totals.upstreamAmount : balance.totals.supplyAmount }} · 本级价差 ¥{{ first ? balance.totals.firstMargin : balance.totals.secondMargin }}</p><small>仅汇总已结算调用；充值不计入利润，计价金额不代表现金收入。</small></div></article>
    <article v-if="!readOnly" class="panel-card"><h2>授权模型与价格</h2><div class="table-scroll"><table><thead><tr><th>模型</th><th>供货状态</th><th>价格与调价通知</th><th>配置</th></tr></thead><tbody><tr v-for="row in rows" :key="row.model.id"><td>{{ row.model.name || row.model.id }}<small>{{ row.model.taskType }}</small></td><td>{{ row.offer?.enabled ? '已启用' : '尚未启用' }}</td><td><small v-for="item in row.sale?.components || []" :key="`${item.meter}:${item.phase}:${JSON.stringify(item.dimensions)}`">当前 {{ item.meter }} {{ item.phase }} ¥{{ item.amount }}/{{ item.unitSize }}</small><div v-for="notice in row.priceNotices || []" :key="notice.effectiveAt"><strong>{{ new Date(notice.effectiveAt).toLocaleString() }} 生效</strong><small v-for="item in notice.sale.components" :key="`${item.meter}:${item.phase}:${JSON.stringify(item.dimensions)}`">{{ item.meter }} {{ item.phase }} ¥{{ item.amount }}/{{ item.unitSize }}</small><small>每元积分 {{ notice.pointsPerCny }} · 消费倍率 {{ notice.consumptionMultiplier }}</small></div></td><td><button class="secondary-button" @click="edit(row)">设置加价</button></td></tr></tbody></table></div><p v-if="!rows.length">暂无可供货模型，请先核对中心授权和上游配置。</p></article>
    <form v-if="selected && !readOnly" class="panel-card" @submit.prevent="save"><h2>{{ selected.model.name }} · 加价设置</h2><p>首次配置可立即启用；已有价格、积分换算或消费倍率的变更至少提前24小时。停供可立即生效，已有调价生效前不能覆盖。</p><label>调价生效时间<input v-model="form.effectiveAt" type="datetime-local" /><small>留空为24小时后；只改启停不改变已发布调价。</small></label><label><input v-model="form.enabled" type="checkbox" />启用供货</label><label>每人民币对应积分<input v-model="form.pointsPerCny" type="text" inputmode="decimal" required /></label><label>终端消费倍率<input v-model="form.consumptionMultiplier" type="text" inputmode="decimal" required /></label><p>倍率仅调整终端积分，可设为0；会员折扣在受理时核对，上游供货费用照常结算。赠送积分消费不等于现金收入。</p><div class="markup-grid"><section><h3>用户售价加价额</h3><label v-for="item in saleMarkup" :key="`${item.meter}:${item.phase}:${JSON.stringify(item.dimensions)}`">{{ item.meter }} · {{ item.phase }} {{ item.dimensions }}<input v-model="item.amount" type="text" inputmode="decimal" required /></label></section><section v-if="first"><h3>二级供货加价额</h3><label v-for="item in supplyMarkup" :key="`${item.meter}:${item.phase}:${JSON.stringify(item.dimensions)}`">{{ item.meter }} · {{ item.phase }} {{ item.dimensions }}<input v-model="item.amount" type="text" inputmode="decimal" required /></label></section></div><button class="primary-button" :disabled="busy">保存</button><button type="button" class="secondary-button" @click="selected = null">取消</button></form>
    <form v-if="!readOnly && first && auth.can('organizations.children.manage')" class="panel-card" @submit.prevent="topup"><h2>审核二级充值</h2><p>确认已线下收款后入账；同一凭证只能入账一次。</p><label>二级组织ID<input v-model="credit.childId" required /></label><label>收款金额（元）<input v-model="credit.amount" type="text" inputmode="decimal" required /></label><label>收款凭证编号<input v-model="credit.receipt" minlength="3" required /></label><button class="primary-button" :disabled="busy">审核入账</button></form>
    <p v-if="readOnly" role="status">当前仅查看供货历史账务；不开放新供货、充值或调价。所有者可处理本组织已结算调用的积分退回；一级所有者还可处理供货冲正。</p>
    <article v-if="balance?.totals" class="panel-card"><h2>账务调整</h2><p>供货退款 ¥{{ balance.totals.supplyRefunds || '0.000000' }} · 充值纠错 ¥{{ balance.totals.prepaymentCorrections || '0.000000' }} · 调整后本级价差 ¥{{ balance.totals.netMargin || '0.000000' }}</p><p>已退积分 {{ balance.totals.refundedPoints || '0.000000' }} · 撤回计价金额 ¥{{ balance.totals.terminalRefunds || '0.000000' }} · 调整后计价金额 ¥{{ balance.totals.netSalesAmount || '0.000000' }}</p><small>退积分撤回本级计价金额，上游费用保留；这不是现金退款。充值纠错不计利润，原调用和流水保留。</small></article>
    <article v-if="balance" class="panel-card"><h2>最近供货流水</h2><div class="table-scroll"><table><thead><tr><th>组织</th><th>流水</th><th>金额</th><th>说明</th><th>操作</th></tr></thead><tbody><tr v-for="entry in balance.entries" :key="entry.id"><td>{{ entry.organizationId }}</td><td>{{ entry.kind }}<small>{{ entry.id }}</small></td><td>{{ entry.amount }}</td><td>{{ entry.reason || '' }}<small v-if="entry.kind === 'terminal_refund'">退回 {{ entry.points }} 积分 · 原调用 {{ entry.requestId }}</small><small v-if="entry.reverses">关联原流水 {{ entry.reverses }}</small></td><td><button v-if="canReverse && ['credit','supply_debit'].includes(entry.kind) && !balance.entries.some(row => row.reverses === entry.id)" class="secondary-button" :disabled="busy" @click="selectReversal(entry)">{{ entry.kind === 'credit' ? '充值纠错' : '供货退款' }}</button></td></tr></tbody></table></div></article>
    <form v-if="reversalEntry" class="panel-card" @submit.prevent="reverse"><h2>确认追加冲正</h2><p>原流水 {{ reversalEntry.id }}，原金额 ¥{{ reversalEntry.amount }}。本操作仅调整二级供货钱包，不向外部账户打款，不退回终端积分，也不撤销官方供应商消费。</p><label>原因<input v-model="reversalReason" minlength="3" maxlength="500" required /></label><button class="primary-button" :disabled="busy">确认全额冲正</button><button type="button" class="secondary-button" @click="reversalEntry = null">取消</button></form>
    <article v-if="balance" class="panel-card"><h2>最近100条调用与价差</h2><div class="table-scroll"><table><thead><tr><th>请求</th><th>状态</th><th>原价</th><th>折后计价金额</th><th>供货支出</th><th>营销补贴</th><th>本级价差</th><th>积分售后</th></tr></thead><tbody><tr v-for="item in balance.usage" :key="item.requestId"><td>{{ item.requestId }}</td><td>{{ item.state }}</td><td>{{ item.listSalesAmount || '待结算' }}</td><td>{{ item.salesAmount || '待结算' }}</td><td>{{ (first ? item.upstreamAmount : item.supplyAmount) || '待结算' }}</td><td>{{ item.marketingSubsidy || '待结算' }}</td><td>{{ (first ? item.firstMargin : item.secondMargin) || '待结算' }}</td><td><button v-if="canRefundPoints && item.canRefundPoints" class="secondary-button" :disabled="busy" @click="selectRefund(item)">退回积分</button></td></tr></tbody></table></div></article>
    <form v-if="refundUsage" class="panel-card" @submit.prevent="refundPoints"><h2>确认全额退回积分</h2><p>原调用 {{ refundUsage.requestId }}，将退回该调用实际扣除的 {{ refundUsage.points }} 积分。原调用与上游供货费用保留；本操作不向外部账户打款。</p><label>退回依据<input v-model="refundReason" minlength="3" maxlength="500" required /></label><button class="primary-button" :disabled="busy">确认退回积分</button><button type="button" class="secondary-button" @click="refundUsage = null">取消</button></form>
  </section>
</template>
<style scoped>.supply-page article,.supply-page form{padding:24px;margin:18px 0}.supply-page label{display:flex;gap:8px;align-items:center;margin:12px 0}.supply-page input{padding:8px;max-width:320px}.supply-page small{display:block}.table-scroll{overflow:auto}.supply-page table{width:100%;text-align:left;border-collapse:collapse}.supply-page td,.supply-page th{padding:12px;border-bottom:1px solid #e2e8f0}.markup-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:20px}</style>
